<template><view class="growth-page" :class="{'motion-reduced':reducedMotion}">
 <view class="growth-hero journey-hero"><view><text class="growth-title">每一小步，都算数</text><text class="growth-subtitle">记录是为了认识自己，无需和任何人比较。</text></view><image src="/static/xiaozhi-caring.png" mode="aspectFit" aria-label="小织陪你回看成长"/></view>
 <view v-if="error" class="growth-error">{{error}}<button class="growth-button secondary" @click="load">重新加载</button></view><text v-if="loading" class="growth-muted">正在整理你的旅程…</text>
 <template v-if="data">
 <view class="growth-card growth-row growth-spread"><view v-for="s in stats" :key="s.label"><text class="metric">{{s.value}}</text><text class="growth-muted">{{s.label}}</text></view></view>
 <view class="growth-card"><text class="growth-card-title">今天，感觉如何？</text><view class="growth-row moods"><button v-for="(m,i) in moods" :aria-pressed="mood===i+1" :key="m" :class="['growth-choice',{selected:mood===i+1}]" @click="mood=i+1">{{m}}</button></view><textarea class="growth-input growth-textarea" v-model="note" aria-label="今日感受备注，选填" maxlength="500" placeholder="想留下一句话吗？（选填）"/><checkbox-group @change="consent=$event.detail.value.length>0"><label class="growth-consent"><checkbox value="yes" :checked="consent" color="#2f7566"/>同意将本次感受加密保存到我的成长记录，可随时清除。</label></checkbox-group><button class="growth-button" :disabled="busy||!consent||!mood" @click="save">{{busy?'正在保存…':'保存今日感受'}}</button></view>
 <view class="growth-card"><view class="growth-row growth-spread"><text class="growth-card-title">{{monthLabel}}</text><view class="growth-row"><button class="calendar-nav" @click="changeMonth(-1)">上月</button><button class="calendar-nav" @click="changeMonth(1)">下月</button></view></view><view class="calendar"><text v-for="w in ['一','二','三','四','五','六','日']" :key="w" class="week">{{w}}</text><button v-for="(d,i) in calendar" :disabled="!d" :aria-label="d ? d+(dayRecords[d]?' 有感受记录':' 未记录') : '空白日期'" :key="i" :class="['day',{recorded:d&&dayRecords[d],selected:d&&selectedDay===d}]" @click="selectedDay=d"><text>{{d?Number(d.slice(-2)):''}}</text><text v-if="d&&dayRecords[d]" class="dot">●</text></button></view><text class="growth-muted">{{selectedDay && dayRecords[selectedDay] ? selectedDay+' · '+moods[dayRecords[selectedDay].mood-1]+'\n'+(dayRecords[selectedDay].note||'') : '点选已标记的日期，回看当天的感受。'}}</text></view>
 <view class="growth-card"><text class="growth-card-title">近两周的感受</text><text class="growth-muted">只呈现你记录的感受，空白日不作推断。</text><view class="mood-trend"><button v-for="d in trendDays" :key="d.key" class="trend-column" :aria-label="d.key+(d.record?' '+moods[d.record.mood-1]:' 未记录')" @click="selectedDay=d.key;month=new Date(d.key.slice(0,7)+'-01T12:00:00')"><view class="trend-track"><view v-if="d.record" class="trend-bar" :style="{height:d.record.mood*20+'%'}"/><text v-else class="trend-empty">—</text></view><text>{{d.day}}</text></button></view><text class="growth-muted">这是主观感受回看，不用于判断干预效果。</text></view><view class="growth-card"><text class="growth-card-title">我的里程碑</text><view class="growth-row"><text v-for="b in data.badges" :key="b" class="growth-tag">{{b}}</text><text v-if="!data.badges.length" class="growth-muted">完成一次创作，点亮第一枚纪念徽章。</text></view><text class="growth-muted">连续记录 {{data.streak}} 天 · 不必为了连续天数勉强自己。</text></view>
 <JourneyInsights :records="data.records" :limit="data.limit" :truncated="data.truncated"/><view class="growth-card"><text class="growth-card-title">最近记录</text><text v-if="!history.length" class="growth-muted">还没有记录，从今天开始也很好。</text><view v-for="r in history.slice(0,historyLimit)" :key="r.id" class="history"><text>{{r.kind==='REFLECTION'?(r.title||'创作感受'):r.scale+' · '+(r.kind==='DRAFT'?'未完成':r.score+' 分')}}</text><text class="growth-muted">{{r.date.slice(0,16)}}{{r.kind==='REFLECTION'?' · '+moods[r.afterMood-1]:''}}</text><text v-if="r.kind==='ASSESSMENT'" class="growth-muted">{{r.message}} 结果不构成诊断。</text><text v-if="r.note" class="growth-muted">{{r.note}}</text><button v-if="r.kind==='DRAFT'" class="growth-button secondary" @click="resume(r.scale)">继续作答</button></view><button v-if="history.length>historyLimit" class="growth-button secondary" @click="historyLimit+=20">查看更多记录</button><text class="growth-muted">已载入 {{data.records.length}} 条记录{{data.truncated?'，较早记录未载入':''}}。</text></view>
 <button class="growth-button danger" :disabled="busy" @click="erase">清除我的感受与自评记录</button>
 </template><text class="growth-foot">本系统不能替代专业心理咨询</text>
</view></template>
<script setup>
import JourneyInsights from '../../components/JourneyInsights.vue'
import {useInteraction} from '../../composables/useInteraction'
const {reducedMotion}=useInteraction()

import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {request} from '../../utils/request'
const historyLimit=ref(20)
const data=ref(null),loading=ref(false),busy=ref(false),error=ref(''),mood=ref(0),note=ref(''),consent=ref(false),selectedDay=ref(''),month=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1));const moods=['很低落','有些低落','平静','还不错','很开心']
const stats=computed(()=>[{label:'创作天数',value:data.value.days},{label:'完成创作',value:data.value.completed},{label:'专注分钟',value:Math.floor(data.value.flowSeconds/60)}]);const dayRecords=computed(()=>Object.fromEntries((data.value?.records||[]).filter(r=>r.kind==='MOOD').map(r=>[r.key,r])));const history=computed(()=>(data.value?.records||[]).filter(r=>['REFLECTION','ASSESSMENT','DRAFT'].includes(r.kind)))
const trendDays=computed(()=>Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return{key,day:d.getDate(),record:dayRecords.value[key]}}))
const monthLabel=computed(()=>month.value.getFullYear()+' 年 '+(month.value.getMonth()+1)+' 月');const calendar=computed(()=>{const y=month.value.getFullYear(),m=month.value.getMonth();return [...Array((month.value.getDay()+6)%7).fill(''),...Array.from({length:new Date(y,m+1,0).getDate()},(_,i)=>y+'-'+String(m+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'))]});function changeMonth(n){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1)}
async function load(){loading.value=true;error.value='';try{data.value=await request({url:'/api/growth/journey'});const today=new Date().toLocaleDateString('sv-SE');const record=dayRecords.value[today];if(record){mood.value=record.mood;note.value=record.note||''}}catch(e){error.value=e.message||'加载失败'}finally{loading.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await request({url:'/api/growth/mood',method:'PUT',data:{mood:mood.value,note:note.value,consent:consent.value}});uni.showToast({title:'已保存',icon:'success'});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function resume(scale){uni.navigateTo({url:'/pages/assessment/index?scale='+scale})}
function erase(){uni.showModal({title:'清除个人记录',content:'永久清除心情、自评、创作感受与活动反馈。作品、创作会话和报名不受影响。此操作不能撤销。',confirmText:'确认清除',success:async r=>{if(!r.confirm||busy.value)return;busy.value=true;try{await request({url:'/api/growth/records',method:'DELETE'});mood.value=0;note.value='';await load()}catch(e){error.value=e.message}finally{busy.value=false}}})}onShow(load)
</script><style src="../../styles/growth.css"></style><style scoped>.calendar-nav{font-size:24rpx;line-height:2;background:transparent;color:#2f7566;padding:0;margin:0}.calendar-nav::after{border:0}.day.selected{outline:2rpx solid #2f7566}.mood-trend{display:flex;gap:5rpx;margin:24rpx 0}.trend-column{flex:1;min-width:0;margin:0;padding:0;background:transparent;color:#688075;font-size:19rpx;line-height:2}.trend-column::after{border:0}.trend-track{height:130rpx;display:flex;align-items:flex-end;justify-content:center}.trend-bar{width:60%;background:#75baa2;border-radius:6rpx 6rpx 0 0;min-height:8rpx;transition:height .2s ease}.trend-empty{align-self:center;color:#a0b3a8}.moods .growth-choice{width:auto;line-height:1.6;margin:12rpx 0;min-height:76rpx}.metric{display:block;font-size:44rpx;font-weight:650}.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:8rpx;margin:20rpx 0}.week{text-align:center;color:#708585;font-size:23rpx}.day{height:68rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:12rpx;font-size:25rpx}.recorded{background:#e7f4ed;color:#2f7566}.dot{font-size:12rpx}.history{padding:24rpx 0;border-bottom:1rpx solid var(--zy-border,#e2e9e9);display:flex;flex-direction:column;gap:10rpx}.moods{gap:8rpx}.moods .growth-choice{padding:14rpx 10rpx;font-size:23rpx;flex:1;text-align:center}</style>

<style scoped>.growth-page{max-width:1180px;margin:auto}.journey-hero{display:flex;align-items:center;justify-content:space-between;gap:20rpx}.journey-hero image{width:140rpx;height:160rpx;flex-shrink:0}.calendar .day{padding:0;margin:0;width:100%;min-height:44px;line-height:1.3;background:transparent;color:#233d34}.calendar .day.recorded{background:#e7f4ed}.calendar .day::after{border:0}.calendar .day[disabled]{opacity:0}.calendar-nav{min-height:44px;min-width:44px}.history{overflow-wrap:anywhere}.growth-page .metric{font-variant-numeric:tabular-nums}</style>
